import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:geolocator/geolocator.dart';import 'package:go_router/go_router.dart';import '../../../../core/constants/app_colors.dart';import '../../../../core/router/route_names.dart';import '../../../../core/constants/app_spacing.dart';import '../../../../core/widgets/app_text_field.dart';import '../../../../core/widgets/primary_button.dart';import '../../../../l10n/app_localizations.dart';import '../../../auth/presentation/providers/auth_provider.dart';import '../../../profile/data/repositories/profile_repository_impl.dart';import '../../../profile/domain/entities/profile_entities.dart';import '../../../profile/domain/usecases/profile_usecases.dart';import '../../../../core/providers/profile_status_provider.dart';
class CustomerProfileScreen extends ConsumerStatefulWidget{const CustomerProfileScreen({super.key});@override ConsumerState<CustomerProfileScreen> createState()=>_CustomerProfileScreenState();}
class _CustomerProfileScreenState extends ConsumerState<CustomerProfileScreen>{final name=TextEditingController(),address=TextEditingController(),city=TextEditingController(text:'Karachi'),area=TextEditingController();double? lat,lng;bool loading=false;String? error;@override void dispose(){name.dispose();address.dispose();city.dispose();area.dispose();super.dispose();}@override Widget build(BuildContext c){final l=AppLocalizations.of(c)!;final auth=ref.watch(authStateProvider);if(auth.valueOrNull==null)return const SizedBox.shrink();return Scaffold(backgroundColor:AppColors.scaffoldBackground,appBar:AppBar(title:Text(l.customerProfile)),body:SafeArea(child:SingleChildScrollView(padding:const EdgeInsets.all(AppSpacing.xxl),child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(l.profileCompletion,style:Theme.of(c).textTheme.headlineMedium),const SizedBox(height:AppSpacing.sm),Text(l.profileCompletionHelper,style:Theme.of(c).textTheme.bodyMedium),const SizedBox(height:AppSpacing.xxl),AppTextField(controller:name,label:l.fullName),const SizedBox(height:AppSpacing.md),AppTextField(controller:address,label:l.addressLine),const SizedBox(height:AppSpacing.md),AppTextField(controller:city,label:l.city),const SizedBox(height:AppSpacing.md),AppTextField(controller:area,label:l.area),const SizedBox(height:AppSpacing.lg),OutlinedButton.icon(onPressed:_locate,icon:const Icon(Icons.my_location_rounded),label:Text(lat==null?l.useCurrentLocation:'${l.location} ✓')),if(error!=null)Padding(padding:const EdgeInsets.only(top:AppSpacing.md),child:Text(error!,style:const TextStyle(color:AppColors.error))),const SizedBox(height:AppSpacing.xxl),PrimaryButton(label:l.saveProfile,isLoading:loading,isEnabled:!loading,onPressed:()=>_save(l))]))));}Future<void> _locate()async{final p=await Geolocator.requestPermission();if(p==LocationPermission.denied||p==LocationPermission.deniedForever){setState(()=>error=AppLocalizations.of(context)!.locationUnavailable);return;}final pos=await Geolocator.getCurrentPosition();setState((){lat=pos.latitude;lng=pos.longitude;error=null;});}Future<void> _save(AppLocalizations l)async{if(name.text.trim().isEmpty||address.text.trim().isEmpty||city.text.trim().isEmpty||area.text.trim().isEmpty||lat==null){setState(()=>error=l.profileRequired);return;}setState(()=>loading=true);final user=ref.read(authStateProvider).valueOrNull!;await SaveCustomerProfile(ref.read(profileRepositoryProvider)).call(user.id,CustomerProfileDraft(fullName:name.text.trim(),addressLine:address.text.trim(),city:city.text.trim(),area:area.text.trim(),latitude:lat!,longitude:lng!));ref.invalidate(profileStatusProvider);if(mounted)context.go(RouteNames.customerHome);}}
